<?php ui_header('Hoàn thiện hồ sơ','Hồ sơ đầy đủ giúp tăng matching score, hiển thị tốt hơn trong network và nhận được nhiều cơ hội việc làm phù hợp.');$labels=['full_name'=>'Thêm họ và tên','headline'=>'Thêm chức danh chuyên môn','about'=>'Thêm giới thiệu bản thân','location'=>'Thêm địa điểm','avatar'=>'Tải ảnh đại diện','cover'=>'Tải ảnh bìa','experience'=>'Thêm kinh nghiệm','education'=>'Thêm học vấn','skills'=>'Thêm ít nhất 3 kỹ năng','projects'=>'Thêm dự án','certifications'=>'Thêm chứng chỉ','languages'=>'Thêm ngôn ngữ','links'=>'Thêm liên kết portfolio','cv'=>'Tải CV'];$targets=['experience'=>'experiences','education'=>'educations','links'=>'languages','cv'=>'cv'];$next=false; ?>
<div class="onboarding-page"><section class="panel section"><div class="section-title"><div><h2>Tiến độ hoàn thiện</h2><p class="muted"><?= $checklist['completion']===100?'Hồ sơ hoàn chỉnh! Bạn đã sẵn sàng ứng tuyển.':'Hoàn thiện hồ sơ để tăng cơ hội nghề nghiệp.' ?></p></div><strong class="completion-number"><?= (int)$checklist['completion'] ?>%</strong></div><progress max="100" value="<?= (int)$checklist['completion'] ?>" aria-label="Tiến độ hoàn thiện hồ sơ"></progress></section><section class="panel section"><h2>Checklist của bạn</h2><ul class="onboarding-checklist"><?php foreach($checklist['items'] as $item):$isNext=!$next&&!$item['done'];if($isNext)$next=true; ?><li class="<?= $item['done']?'complete':($isNext?'next':'') ?>"><?= ui_icon($item['done']?'check':'target',22) ?><span><?= e($labels[$item['key']]??$item['label']) ?></span><?php if(!$item['done']): ?><a class="button ghost" href="/profile?edit=true#editor-<?= e($targets[$item['section']]??$item['section']) ?>">Làm ngay <?= ui_icon('arrow',14) ?></a><?php endif; ?></li><?php endforeach; ?></ul></section><section class="panel section"><h2>Thiết lập hồ sơ nhanh</h2><p class="muted">Cập nhật nhanh các trường cơ bản để hoàn tất onboarding.</p><form data-api="/users/me/profile" data-method="PATCH" data-reload><div class="grid two"><?php foreach(['fullName'=>'Họ tên','location'=>'Địa điểm'] as $field=>$label): ?><label><?= e($label) ?><input name="<?= e($field) ?>" value="<?= e($data[$field]??'') ?>" <?= $field==='fullName'?'required':'' ?>></label><?php endforeach; ?></div><label>Headline<input name="headline" value="<?= e($data['headline']??'') ?>" placeholder="VD: Senior Frontend Engineer @ TechCorp"></label><label>Giới thiệu bản thân<textarea name="about"><?= e($data['about']??'') ?></textarea></label><div class="field-end"><button type="submit">Lưu hồ sơ</button></div></form></section></div>